from collections import deque, Counter,defaultdict

def comps(grid, color, region):
    r0,r1,c0,c1=region
    seen=set(); out=[]
    for r in range(r0,r1):
      for c in range(c0,c1):
       if grid[r][c]!=color or (r,c) in seen: continue
       q=[(r,c)]; seen.add((r,c)); cells=[]
       while q:
        p=q.pop();cells.append(p)
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
         n=(p[0]+dr,p[1]+dc)
         if r0<=n[0]<r1 and c0<=n[1]<c1 and n not in seen and grid[n[0]][n[1]]==color:
          seen.add(n);q.append(n)
       out.append(cells)
    return out

def normshape(cells):
    mi=min(r for r,c in cells); mj=min(c for r,c in cells)
    return tuple(sorted((r-mi,c-mj) for r,c in cells))
